#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'build/PrePoMax-CodeAster')
path = root / 'PrePoMax' / 'AsterMaxAI' / 'AsterMaxStepMeshHarness.cs'
text = path.read_text(encoding='utf-8-sig')

# Emit request evidence as soon as the harness starts. This makes failures before CAD import,
# geometry binding, or NetGen invocation diagnosable instead of looking like a missing file.
entry_anchor = '''            string evidencePath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_EVIDENCE_PATH");\n            string stepPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_PATH");'''
entry_replacement = '''            string evidencePath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_EVIDENCE_PATH");\n            string stepPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_PATH");\n            string c882MaxHText = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_MAXH_MM");\n            string c882CfgPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_CONFIG_EVIDENCE_PATH");\n            if (!String.IsNullOrWhiteSpace(c882CfgPath))\n            {\n                string c882CfgDir = Path.GetDirectoryName(c882CfgPath);\n                if (!String.IsNullOrWhiteSpace(c882CfgDir)) Directory.CreateDirectory(c882CfgDir);\n                File.WriteAllText(c882CfgPath, "{\\n  \\\"schema\\\": \\\"astermax.c8.82.native-netgen-size.v3\\\",\\n" +\n                    "  \\\"request_environment_seen\\\": true,\\n" +\n                    "  \\\"requested_maxh_raw\\\": " + Json(c882MaxHText) + ",\\n" +\n                    "  \\\"part_specific_parameters_admitted\\\": false,\\n" +\n                    "  \\\"native_create_mesh_started\\\": false,\\n" +\n                    "  \\\"industrial_validation\\\": false,\\n" +\n                    "  \\\"ansys_equivalence\\\": false\\n}", Encoding.UTF8);\n            }'''
if entry_anchor not in text:
    raise SystemExit('C8.82 request-evidence anchor not found; refusing non-deterministic patch')
text = text.replace(entry_anchor, entry_replacement, 1)

anchor = '''                meshedPartName = geometry.Parts.First().Key;\n                // Pinned native path: Controller.CreateMesh -> CreateMeshFromBrep -> NetGenMesher -> ImportGeneratedMesh.\n                createMeshReturned = _controller.CreateMesh(meshedPartName);'''
replacement = '''                meshedPartName = geometry.Parts.First().Key;\n\n                // C8.82: explicit native NetGen mesh-size contract for sensitivity studies.\n                // The product GUI stores both selected geometry IDs and a deep-cloned Selection graph.\n                // Mirroring that contract is required because AddMeshingParametersCommand validates CreationData.\n                if (!String.IsNullOrWhiteSpace(c882CfgPath) && String.IsNullOrWhiteSpace(c882MaxHText))\n                    throw new InvalidOperationException("C8.82 mesh-size evidence was requested but ASTERMAX_STEP_MESH_MAXH_MM was not inherited by AsterMax.");\n                if (!String.IsNullOrWhiteSpace(c882MaxHText))\n                {\n                    double requestedMaxH;\n                    if (!Double.TryParse(c882MaxHText, NumberStyles.Float, CultureInfo.InvariantCulture, out requestedMaxH) ||\n                        !Finite(requestedMaxH) || requestedMaxH <= 0)\n                        throw new InvalidOperationException("ASTERMAX_STEP_MESH_MAXH_MM must be a finite value > 0 mm.");\n\n                    int targetPartId = geometry.Parts[meshedPartName].PartId;\n                    MeshingParameters p = new MeshingParameters("C8_82_MaxH_" + requestedMaxH.ToString("0.###", CultureInfo.InvariantCulture));\n                    p.RelativeSize = false;\n                    p.MaxH = requestedMaxH;\n                    p.MinH = 0;\n                    p.SecondOrder = true;\n                    p.CreationIds = new int[] { targetPartId };\n                    CaeGlobals.Selection geometrySelection = new CaeGlobals.Selection();\n                    geometrySelection.SelectItem = CaeGlobals.vtkSelectItem.Part;\n                    geometrySelection.Add(new CaeGlobals.SelectionNodeIds(CaeGlobals.vtkSelectOperation.Add, false, new int[] { targetPartId }, true));\n                    p.CreationData = geometrySelection;\n                    _controller.AddMeshingParametersCommand(p);\n\n                    MeshingParameters admitted = _controller.GetMeshingParameters(p.Name);\n                    bool admittedOk = admitted != null && admitted.CreationIds != null && admitted.CreationIds.Length == 1 &&\n                        admitted.CreationIds[0] == targetPartId && admitted.CreationData != null &&\n                        admitted.CreationData.IsGeometryBased() && !admitted.RelativeSize &&\n                        Math.Abs(admitted.MaxH - requestedMaxH) <= 1e-12;\n                    if (!admittedOk)\n                        throw new InvalidOperationException("C8.82 GUI-equivalent part-specific MeshingParameters admission failed.");\n\n                    if (!String.IsNullOrWhiteSpace(c882CfgPath))\n                    {\n                        File.WriteAllText(c882CfgPath, "{\\n  \\\"schema\\\": \\\"astermax.c8.82.native-netgen-size.v4\\\",\\n" +\n                            "  \\\"request_environment_seen\\\": true,\\n" +\n                            "  \\\"requested_maxh_raw\\\": " + Json(c882MaxHText) + ",\\n" +\n                            "  \\\"requested_maxh_mm\\\": " + requestedMaxH.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                            "  \\\"target_geometry_part_id\\\": " + targetPartId.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                            "  \\\"part_specific_parameters_admitted\\\": true,\\n" +\n                            "  \\\"creation_data_geometry_based\\\": true,\\n" +\n                            "  \\\"relative_size\\\": false,\\n" +\n                            "  \\\"second_order_requested\\\": true,\\n" +\n                            "  \\\"native_create_mesh_started\\\": true,\\n" +\n                            "  \\\"industrial_validation\\\": false,\\n" +\n                            "  \\\"ansys_equivalence\\\": false\\n}", Encoding.UTF8);\n                    }\n                }\n\n                // Pinned native path: Controller.CreateMesh -> CreateMeshFromBrep -> NetGenMesher -> ImportGeneratedMesh.\n                createMeshReturned = _controller.CreateMesh(meshedPartName);'''
if anchor not in text:
    raise SystemExit('C8.82 mesh-size anchor not found; refusing non-deterministic patch')
text = text.replace(anchor, replacement, 1)
path.write_text(text, encoding='utf-8')
print(f'C8.82 GUI-equivalent part-specific native NetGen mesh-size seam applied: {path}')
